CREATE TABLE users (id BIGSERIAL PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(24) NOT NULL DEFAULT 'participant',is_blocked BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE projects (id BIGSERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT NOT NULL DEFAULT '',owner_id BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE project_members (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(24) NOT NULL DEFAULT 'participant',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(project_id,user_id));
CREATE TABLE sprints (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,start_date TIMESTAMPTZ NOT NULL,end_date TIMESTAMPTZ NOT NULL,is_closed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tasks (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,sprint_id BIGINT REFERENCES sprints(id) ON DELETE SET NULL,title VARCHAR(200) NOT NULL,description TEXT NOT NULL DEFAULT '',status VARCHAR(24) NOT NULL DEFAULT 'todo',priority VARCHAR(24) NOT NULL DEFAULT 'medium',assignee_id BIGINT REFERENCES users(id) ON DELETE SET NULL,creator_id BIGINT NOT NULL REFERENCES users(id),due_date TIMESTAMPTZ,attachment_path VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE comments (id BIGSERIAL PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE sprint_tasks (id BIGSERIAL PRIMARY KEY,sprint_id BIGINT NOT NULL REFERENCES sprints(id) ON DELETE CASCADE,task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,UNIQUE(sprint_id,task_id));
CREATE TABLE task_history (id BIGSERIAL PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,actor_id BIGINT NOT NULL REFERENCES users(id),field VARCHAR(60) NOT NULL,old_value TEXT NOT NULL DEFAULT '',new_value TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE refresh_tokens (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE password_reset_tokens (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_tasks_project_status ON tasks(project_id,status); CREATE INDEX idx_tasks_project_priority ON tasks(project_id,priority); CREATE INDEX idx_tasks_title ON tasks(title); CREATE INDEX idx_tasks_due_date ON tasks(due_date); CREATE INDEX idx_members_user ON project_members(user_id); CREATE INDEX idx_comments_task ON comments(task_id); CREATE INDEX idx_history_task_created ON task_history(task_id,created_at DESC);
